import{c as d,Q as r,j as a,m as e}from"./chunks/framework.B2dUnTNU.js";const u=JSON.parse('{"title":"🚗 车辆","description":"","frontmatter":{},"headers":[],"relativePath":"vehicles/index.md","filePath":"vehicles/index.md","lastUpdated":1778834040000}'),i={name:"vehicles/index.md"};function l(h,t,o,n,s,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="🚗-车辆" tabindex="-1">🚗 车辆 <a class="header-anchor" href="#🚗-车辆" aria-label="Permalink to &quot;🚗 车辆&quot;">​</a></h1><h2 id="车型对比" tabindex="-1">车型对比 <a class="header-anchor" href="#车型对比" aria-label="Permalink to &quot;车型对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>车型</th><th>速度</th><th>马力</th><th>行李箱容量</th><th>座位</th><th>噪音</th><th>适合</th></tr></thead><tbody><tr><td>Chevalier Nyala</td><td>中</td><td>380</td><td>120</td><td>5</td><td>40</td><td>通用家庭车</td></tr><tr><td>Chevalier Cerise</td><td>中</td><td>340</td><td>100</td><td>4</td><td>40</td><td>小型轿车</td></tr><tr><td>Dash Bulldriver</td><td>中</td><td>420</td><td>130</td><td>6</td><td>50</td><td>搬家运货</td></tr><tr><td>Franklin All-Terrain</td><td>中</td><td>390</td><td>110</td><td>6</td><td>55</td><td>越野搬家</td></tr><tr><td>Chevalier D6</td><td>高</td><td>450</td><td>90</td><td>2</td><td>70</td><td>速度快但容量小</td></tr><tr><td>Chevalier Cossette</td><td>极高</td><td>500</td><td>60</td><td>2</td><td>80</td><td>跑车，声音大</td></tr><tr><td>Chevalier Primani</td><td>中</td><td>400</td><td>120</td><td>4</td><td>45</td><td>警车型，稳</td></tr><tr><td>Step Van</td><td>低</td><td>370</td><td>250</td><td>2</td><td>50</td><td>移动仓库</td></tr><tr><td>Pickup Truck</td><td>中</td><td>410</td><td>150</td><td>2</td><td>55</td><td>皮卡，平衡</td></tr><tr><td>Ambulance</td><td>高</td><td>480</td><td>110</td><td>3</td><td>60</td><td>速度快</td></tr><tr><td>Fire Truck</td><td>中</td><td>500</td><td>200</td><td>6</td><td>60</td><td>超大容量 + 6 座</td></tr></tbody></table><h2 id="🔧-关键零件" tabindex="-1">🔧 关键零件 <a class="header-anchor" href="#🔧-关键零件" aria-label="Permalink to &quot;🔧 关键零件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>零件</th><th>常见问题</th><th>修理工具</th></tr></thead><tbody><tr><td>引擎 (Engine)</td><td>不能启动或转速不稳</td><td>扳手 + 螺丝刀 (Lv8 机械)</td></tr><tr><td>油箱 (Gas Tank)</td><td>漏油、没油</td><td>直接换件</td></tr><tr><td>电池 (Battery)</td><td>没电、老化</td><td>充电器 或 直接换电池</td></tr><tr><td>轮胎 (Tire)</td><td>爆胎、打滑</td><td>扳手 + 千斤顶 + 备用轮胎</td></tr><tr><td>消音器 (Muffler)</td><td>噪音暴增</td><td>扳手</td></tr><tr><td>刹车 (Brakes)</td><td>刹车距离变长</td><td>扳手</td></tr><tr><td>悬挂 (Suspension)</td><td>跑偏</td><td>扳手</td></tr><tr><td>车窗 (Window)</td><td>碎了</td><td>换玻璃</td></tr><tr><td>门 (Door)</td><td>坏了</td><td>扳手 (换门)</td></tr></tbody></table><h2 id="🚙-操作指南" tabindex="-1">🚙 操作指南 <a class="header-anchor" href="#🚙-操作指南" aria-label="Permalink to &quot;🚙 操作指南&quot;">​</a></h2><h3 id="热车-hotwire" tabindex="-1">热车 (Hotwire) <a class="header-anchor" href="#热车-hotwire" aria-label="Permalink to &quot;热车 (Hotwire)&quot;">​</a></h3><ul><li><strong>要求</strong>: 电工 Lv1 + 机械 Lv2，或 大盗职业（无需技能）</li><li><strong>方法</strong>: 不插钥匙，右键车，选「Hotwire」</li><li><strong>成功率</strong>: 高等级机械降低失败概率</li></ul><h3 id="接油箱" tabindex="-1">接油箱 <a class="header-anchor" href="#接油箱" aria-label="Permalink to &quot;接油箱&quot;">​</a></h3><ul><li>加油站找到加油机</li><li>空汽油桶右键加油机 → 装满</li><li>油桶右键车门旁边的油箱口 → 加进去</li></ul><h3 id="日常维护" tabindex="-1">日常维护 <a class="header-anchor" href="#日常维护" aria-label="Permalink to &quot;日常维护&quot;">​</a></h3><ul><li>定期检查所有零件状态（右键车 → Vehicle Mechanics）</li><li>轮胎和电池是最常需要更换的</li><li>消音器坏了赶快修 → 声音大会拉僵尸</li><li>停在家附近时把车窗摇上，防止僵尸破坏</li></ul><h2 id="📍-常见车辆刷新点" tabindex="-1">📍 常见车辆刷新点 <a class="header-anchor" href="#📍-常见车辆刷新点" aria-label="Permalink to &quot;📍 常见车辆刷新点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>地点</th><th>常见车型</th></tr></thead><tbody><tr><td>民宅车道</td><td>Chevalier Nyala、Cerise 等高概率</td></tr><tr><td>消防局</td><td>Fire Truck (Rosewood)</td></tr><tr><td>警察局</td><td>Chevalier Primani (警车)</td></tr><tr><td>诊所/医院</td><td>Ambulance (救护车)</td></tr><tr><td>加油站</td><td>各种随机</td></tr><tr><td>仓库停车场</td><td>Step Van、Pickup Truck</td></tr><tr><td>酒吧停车场</td><td>各类跑车/肌肉车</td></tr><tr><td>拖车公园</td><td>破旧车辆但零件多</td></tr></tbody></table><h2 id="⚙️-故障排除" tabindex="-1">⚙️ 故障排除 <a class="header-anchor" href="#⚙️-故障排除" aria-label="Permalink to &quot;⚙️ 故障排除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>可能原因</th><th>修复</th></tr></thead><tbody><tr><td>车不启动</td><td>没油、没电、引擎故障</td><td>加油→换电池→修引擎</td></tr><tr><td>噪音巨大</td><td>消音器坏了</td><td>换消音器</td></tr><tr><td>刹车不灵</td><td>刹车坏了</td><td>换刹车片</td></tr><tr><td>方向盘失控</td><td>悬挂坏了</td><td>修悬挂</td></tr><tr><td>跑偏</td><td>轮胎瘪了</td><td>换轮胎</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">最值得抢的车</p><p>Step Van 是游戏中行李箱最大的普通车（250 容量），搬家搜刮两不误。Franklin All-Terrain 则是越野首选，适合在树林和土路穿行。</p></div>',17)])])}const m=d(i,[["render",l]]);export{u as __pageData,m as default};
